#include "target_arithmetic.hpp"
CFPoly tt_poly(const Json& values){std::vector<Z> out;for(const auto& value:values.arr)out.push_back(Z(mpz_class(value.scalar)));return CFPoly(out);}
Class tt_section(QuarticKM& km,const EBPoly& f,const std::array<Z,3>& line,Z ox,Z oy,CFPoly rest,bool corrupt=false){
    Space constraints;std::map<int,int> known;int degree=0;for(int i:km.fibers[0].support)known[i]=2;
    for(auto& entry:known){const auto& point=km.points.at(size_t(entry.first));if(line[0]*Z(point.x)+line[1]*point.y+line[2]!=Z(0))continue;Z t=line[1]!=Z(0)?(Z(point.x)-ox)/line[1]:(point.y-oy)/(-line[0]);while(rest.degree()>0&&rest.eval(t)==Z(0)){rest=rest.exact(CFPoly{-t,Z(1)});++entry.second;}}
    for(const auto& entry:known){const auto& point=km.points.at(size_t(entry.first));int m=entry.second;degree+=m;std::vector<Z> coefficients(size_t(m+1));coefficients[size_t(m)]=Z(1);CFPoly modulus(coefficients),t{Z(0),Z(1)},x{Z(point.x)},y{point.y};bool xlocal=f.partial(1).eval(Z(point.x),point.y)!=Z(0);if(xlocal)x=x+t;else{require(f.partial(0).eval(Z(point.x),point.y)!=Z(0),"closed section smooth chart");y=y+t;}auto derivative=f.partial(xlocal?1:0);for(int precision=1;precision<m;precision*=2){auto error=cm_curve(f,modulus,x,y),d=cm_curve(derivative,modulus,x,y);if(xlocal)y=(y-error*cm_inverse(d,modulus))%modulus;else x=(x-error*cm_inverse(d,modulus))%modulus;}require(cm_curve(f,modulus,x,y).degree()<0,"known section curve jets");std::vector<CFPoly> jets;for(auto exponent:km.mons)jets.push_back((pc_power_mod(x,exponent[0],modulus)*pc_power_mod(y,exponent[1],modulus))%modulus);for(int j=0;j<m;++j){Vector row;for(const auto& jet:jets)row.push_back(jet.at(j));constraints.push_back(row);}}
    if(corrupt)rest=rest+CFPoly{Z(1)};
    if(rest.degree()>0){auto q=rest.monic();CFPoly t{Z(0),Z(1)},x=CFPoly{ox}+t.scale(line[1]),y=CFPoly{oy}-t.scale(line[0]);require(cm_curve(f,q,x,y).degree()<0,"closed remainder actual curve equation");std::vector<CFPoly> residues;for(auto exponent:km.mons)residues.push_back((pc_power_mod(x,exponent[0],q)*pc_power_mod(y,exponent[1],q))%q);for(int j=0;j<q.degree();++j){Vector row;for(const auto& residue:residues)row.push_back(residue.at(j));constraints.push_back(row);}degree+=q.degree();}
    require(degree==12&&constraints.size()==12,"closed section degree12");auto coefficients=nullspace(constraints,int(km.mons.size()));require(coefficients.size()==22,"closed section RR22");Space values;for(const auto& c:coefficients)values.push_back(linear_combination(c,km.v3));auto out=row_basis(values,evaluation_count);require(out.size()==22,"closed section evaluation22");return {out};
}
